def evaluate(expr):
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            tokens.append(num)
        elif expr[i] in '+-*/':
            tokens.append(expr[i])
            i += 1
        elif expr[i] == '(':
            tokens.append('(')
            i += 1
        elif expr[i] == ')':
            tokens.append(')')
            i += 1
        else:
            i += 1

    def parse_expression(start, end):
        ops = []
        stack = []
        i = start
        while i <= end:
            if isinstance(tokens[i], int):
                stack.append(tokens[i])
            elif tokens[i] == '(':
                sub = parse_expression(i + 1, end)
                stack.append(sub)
                i = end
            elif tokens[i] == ')':
                i += 1
            else:
                ops.append(tokens[i])
                i += 1

        while len(ops) > 0:
            if ops[-1] == '*' or ops[-1] == '/':
                op = ops.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '*':
                    stack.append(a * b)
                else:
                    stack.append(int(a / b))
            elif len(ops) >= 2 and ops[-2] in '+-' and ops[-1] in '*':
                ops.append(ops[-2] + ops[-1])
            else:
                break

        while len(ops) > 0:
            op = ops.pop()
            b = stack.pop()
            a = stack.pop()
            if op == '+':
                stack.append(a + b)
            elif op == '-':
                stack.append(a - b)
            elif op == '*':
                stack.append(a * b)
            elif op == '/':
                stack.append(int(a / b))

        return stack[0]

    return parse_expression(0, len(tokens) - 1)
