def semver_compare(a, b):
    def parse(v):
        main, _, meta = v.partition('+')
        main, _, pre = main.partition('-')
        major, minor, patch = map(int, main.split('.'))
        pre_parts = []
        if pre:
            for part in pre.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)
        return major, minor, patch, pre_parts

    ma, mi, pa, pre_a = parse(a)
    mb, mb_min, mb_pa, pre_b = parse(b)

    if ma != mb:
        return 1 if ma > mb else -1
    if mi != mb_min:
        return 1 if mi > mb_min else -1
    if pa != mb_pa:
        return 1 if pa > mb_pa else -1

    if not pre_a and pre_b:
        return 1
    if pre_a and not pre_b:
        return -1

    for a_p, b_p in zip(pre_a, pre_b):
        if isinstance(a_p, int) and isinstance(b_p, int):
            if a_p != b_p:
                return 1 if a_p > b_p else -1
        elif isinstance(a_p, str) and isinstance(b_p, str):
            if a_p != b_p:
                return 1 if a_p > b_p else -1
        else:
            return -1 if isinstance(a_p, int) else 1

    if len(pre_a) != len(pre_b):
        return 1 if len(pre_a) > len(pre_b) else -1

    return 0
