    def tokenize(s):
        tokens = re.findall(r'\d+|[+\-*/^()]', s)
        return tokens

    tokens = tokenize(expr)
    pos = 0

    def parse_expression():
        nonlocal pos
        res = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                res += right
            else:
                res -= right
        return res

    def parse_term():
        nonlocal pos
        res = parse_unary()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == '*':
                res *= right
            else:
                res //= right
                if res < 0:
                    res += 1
        return res

    def parse_unary():
        nonlocal pos
        if tokens[pos] == '-':
            pos += 1
            return -parse_exponent()
        return parse_exponent()

    def parse_exponent():
        nonlocal pos
        res = parse_factor()
        if pos < len(tokens) and tokens[pos] == '^':
            pos += 1
            right = parse_exponent()
            res = res ** right
        return res

    def parse_factor():
        nonlocal pos
        if tokens[pos] == '(':
            pos += 1
            res = parse_expression()
            pos += 1
            return res
        res = int(tokens[pos])
        pos += 1
        return res

    return parse_expression()
