def int_to_words(n):
    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def make_group(num):
        if num == 0:
            return ""
        if num < 10:
            return units[num]
        if num < 20:
            return teens[num - 10]
        if num < 100:
            return tens[num // 10] + ("-" + units[num % 10] if num % 10 != 0 else "")
        return units[num // 100] + " hundred" + (" " + make_group(num % 100) if num % 100 != 0 else "")

    parts = []
    if n // 1_000_000 > 0:
        parts.append(make_group(n // 1_000_000) + " million")
    if n // 1_000 > 0 and n // 1_000 != n // 1_000_000:
        parts.append(make_group(n // 1_000 % 1_000) + " thousand")
    if n % 1_000 > 0 and n % 1_000 != n // 1_000:
        parts.append(make_group(n % 1_000))

    return " ".join(parts)
