import heapq


def task_order(deps):
    graph = {}
    in_degree = {}
    all_tasks = set()

    for task, prerequisites in deps.items():
        all_tasks.add(task)
        for prereq in prerequisites:
            all_tasks.add(prereq)
            graph.setdefault(prereq, []).append(task)
            in_degree[task] = in_degree.get(task, 0) + 1
            if prereq not in in_degree:
                in_degree[prereq] = 0

    queue = [t for t in all_tasks if in_degree.get(t, 0) == 0]
    heapq.heapify(queue)
    order = []

    while queue:
        u = heapq.heappop(queue)
        order.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(order) != len(all_tasks):
        raise ValueError("Cycle detected")

    return order
