import re


def glob_match(name, pattern):
    result = []
    i = 0
    while i < len(pattern):
        if pattern[i] == '*':
            result.append('.*')
            i += 1
        elif pattern[i] == '?':
            result.append('.')
            i += 1
        elif pattern[i] == '[':
            j = i + 1
            if j < len(pattern) and pattern[j] == '!':
                j += 1
                negate = True
            else:
                negate = False
            i = j
            end = pattern.find(']', j)
            if end == -1:
                end = len(pattern)
            chars = pattern[j:end]
            ranges = []
            k = 0
            while k < len(chars):
                if k + 2 < len(chars) and chars[k+1] == '-' and k + 3 <= len(chars):
                    start, stop = chars[k], chars[k+2]
                    ranges.append(re.escape(start) + '-' + re.escape(stop))
                    k += 3
                else:
                    ranges.append(re.escape(chars[k]))
                    k += 1
            if negate:
                result.append(f"[^{''.join(ranges)}]")
            else:
                result.append(f"[{''.join(ranges)}]")
            i = end + 1
        else:
            result.append(re.escape(pattern[i]))
            i += 1
    return bool(re.fullmatch("".join(result), name))
