def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    # words for numbers 0-19
    ones = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
            "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]

    # words for tens 20-90
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def convert_less_than_100(num: int) -> str:
        if num < 20:
            return ones[num]
        else:
            ten_part = tens[num // 10]
            unit_part = ones[num % 10] if num % 10 != 0 else ""
            if unit_part:
                return f"{ten_part}-{unit_part}"
            else:
                return ten_part

    def convert_hundreds(num: int) -> str:
        if num == 0:
            return ""
        elif num < 10:
            return f"{ones[num]} hundred"
        else:
            # num is between 10 and 999
            res = convert_less_than_100(num // 10)  # handles 10-99 correctly with hyphen
            if num % 100 == 0:
                return f"{res} hundred"
            else:
                # num % 100 is between 1 and 99
                rest = convert_less_than_100(num % 100)
                if rest:
                    return f"{res} hundred {rest}"
                else:
                    return f"{res} hundred"

    # handle up to million
    millions = n // 1_000_000
    thousands = (n % 1_000_000) // 1_000
    rest = n % 1_000

    parts = []

    if millions > 0:
        million_part = convert_hundreds(millions)
        if million_part:
            parts.append(million_part + " million")

    if thousands > 0:
        thousand_part = convert_hundreds(thousands)
        if thousand_part:
            parts.append(thousand_part + " thousand")

    if rest > 0:
        rest_part = convert_hundreds(rest)
        if rest_part:
            parts.append(rest_part)

    # filter out empty strings and join
    result_parts = [p for p in parts if p]
    return " ".join(result_parts)
